def solve(a, n):
    """Write a python function to check whether the count of inversion of two types are same or not.

    The two types are global and local inversions:

    * Global inversion: a pair ``(i, j)`` with ``i < j`` and ``a[i] > a[j]``.
    * Local inversion: a pair ``(i, i + 1)`` with ``a[i] > a[i + 1]``.

    Return ``True`` exactly when the counts of the two types are equal.
    """
    if a is None:
        return True

    arr = list(a)
    if n is not None:
        try:
            limit = int(n)
        except (TypeError, ValueError):
            limit = len(arr)
        if limit < 0:
            arr = []
        elif limit < len(arr):
            arr = arr[:limit]

    if len(arr) < 2:
        return True

    local_count = sum(1 for i in range(len(arr) - 1) if arr[i] > arr[i + 1])

    # Count global inversions in O(n log n) via coordinate compression
    # and a Fenwick tree: for each value, previously seen values greater
    # than it form global inversions with it as the right element.
    sorted_unique = sorted(set(arr))
    comp = {value: index + 1 for index, value in enumerate(sorted_unique)}
    bit = [0] * (len(sorted_unique) + 2)

    def bit_sum(index):
        total = 0
        while index > 0:
            total += bit[index]
            index -= index & -index
        return total

    def bit_add(index, delta):
        while index < len(bit):
            bit[index] += delta
            index += index & -index

    global_count = 0
    seen = 0
    for value in arr:
        index = comp[value]
        global_count += seen - bit_sum(index)
        if global_count > local_count:
            return False
        bit_add(index, 1)
        seen += 1

    return global_count == local_count
